def line_total(sku, qty):
    """Total for `qty` units of `sku`, bulk discount applied, rounded to cents."""
    gross = unit_price(sku) * qty
    return round(gross * (1 - bulk_discount(qty)), 2)


def apply_coupon(total, code):
    """Apply coupon `code` to `total`, rounded to cents. Raises ValueError for an unknown code."""
    if code == "SAVE10":
        return round(total * 0.9, 2)
    if code == "FLAT5":
        return round(max(total - 5.00, 0.00), 2)
    raise ValueError(f"unknown coupon code: {code}")

def test_bulk_discount_rate():
    assert bulk_discount(50) == 0.10


def test_save10_takes_ten_percent_off():
    assert apply_coupon(20.00, "SAVE10") == 18.00


def test_flat5_takes_five_off():
    assert apply_coupon(20.00, "FLAT5") == 15.00


def test_flat5_never_below_zero():
    assert apply_coupon(3.00, "FLAT5") == 0.00


def test_unknown_coupon_raises():
    with pytest.raises(ValueError):
        apply_coupon(20.00, "BOGUS")
